import { Carousel, Card } from "march/ui"

// emoji makarası: slaytlar düz metin (her metin kendi slayt kutusunu alır), noktalar numaralı
const faces = ["😀 Neşeli", "😎 Havalı", "🤔 Düşünceli", "😴 Uykulu", "🥳 Kutlamada"]

export function EmojiReel() {
  return <Card title="Bugün nasılsın?">
    <Carousel label="Ruh hâli" perView={2} m:color="brand-orange" dots={(i: number) => String(i + 1)}>
      {faces}
    </Carousel>
  </Card>
}

import { Carousel, Card, Button, Segmented } from "march/ui"
import { arrowLeft, arrowRight } from "march/icons"

// Carousel'in bütün özellikleri bir arada: label, perView (1–4), class, children (düğüm ya da metin), labels,
// arrows, prevIcon / nextIcon, dots (true / false / kendi içeriğin), smooth, swipe ("touch" / true / false) ve m:color
const colors = ["brand-orange", "brand-blue", "brand-green", "brand-purple"] as const

// renkli bir slayt
const Slide = (props: { n: number }) => <Card m:color={colors[props.n % colors.length]}>
  <strong sx={{ text: "xl", color: colors[props.n % colors.length] }}>{props.n + 1}</strong>
</Card>

export function CarouselLab() {
  let $per = 2
  let $swipe = "touch" as "touch" | "mouse" | "off"
  return <div sx={{ flex: "col", gap: 4 }}>
    <div sx={{ flex: "row", gap: 2 }}>
      {[1, 2, 3, 4].map((n) => <Button pressed={$per === n} on:click={() => $per = n}>{`${n} görünen`}</Button>)}
    </div>
    <Segmented aria-label="Kaydırma" size="sm" bind:value={$swipe}
      options={[{ value: "touch", label: "Dokunarak" }, { value: "mouse", label: "Fareyle de" }, { value: "off", label: "Kapalı" }]} />
    {() => <Carousel label="Renkli kartlar" perView={$per as 1} class="lab-main" m:color="brand-purple"
      swipe={$swipe === "mouse" ? true : $swipe === "off" ? false : "touch"}
      labels={{ previous: "Geri", next: "İleri", slide: (n: number) => `Kart ${n}` }}
      prevIcon={arrowLeft} nextIcon={arrowRight} dots={(i: number, active: () => boolean) => (active() ? "●" : String(i + 1))}>
      {Array.from({ length: 6 }, (_, i) => <Slide n={i} />)}
    </Carousel>}
    <Carousel label="Oksuz ve noktasız, anında" arrows={false} dots={false} smooth={false} class="lab-bare">
      {["Bir", "İki", "Üç", "Dört"]}
    </Carousel>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { CarouselLab } from "./CarouselLab.tsx"

// CarouselLab'in testleri: kaydedince Testler sekmesinde çalışır
test("carousel kendi adıyla; kendi düğme adları (labels)", async () => {
  const s = renderTest(() => <CarouselLab />)
  await s.flush()
  const main = s.get(".lab-main")
  expect(main?.getAttribute("aria-roledescription")).toBe("carousel")
  expect(main?.getAttribute("aria-label")).toBe("Renkli kartlar")
  expect(s.find("Geri")).not.toBe(null)
  expect(s.find("İleri")).not.toBe(null)
})

test("perView düğmeyle değişir", async () => {
  const s = renderTest(() => <CarouselLab />)
  expect(s.get(".lab-main")?.classList.contains("m-carousel-2")).toBe(true)
  await s.click("4 görünen")
  await s.flush()
  expect(s.get(".lab-main")?.classList.contains("m-carousel-4")).toBe(true)
})

test("arrows={false} dots={false}: düğme yok; metin slaytları kutu olur; smooth={false} anında", async () => {
  const s = renderTest(() => <CarouselLab />)
  await s.flush()
  const bare = s.get(".lab-bare")
  expect(bare?.querySelectorAll(".m-carousel-btn").length).toBe(0)
  expect(bare?.querySelector(".m-carousel-dots")).toBe(null)
  expect(bare?.querySelectorAll(".m-carousel-text").length).toBe(4)
  expect(bare?.classList.contains("is-instant")).toBe(true)
})

test("kaydırma seçimi carousel'e geçer", async () => {
  const s = renderTest(() => <CarouselLab />)
  await s.click("Fareyle de")
  await s.flush(2)
  expect(s.get(".lab-main")?.classList.contains("is-swipe")).toBe(true)
  await s.click("Kapalı")
  await s.flush(2)
  expect(s.get(".lab-main")?.classList.contains("is-noswipe")).toBe(true)
})
